# 2. PROGRESS REPORTER & STREAMING SUBPROCESS HELPER
# ==============================================================================
STAGE_NAMES = {
    1: "SETUP",
    2: "AUDIO",
    3: "PROJECT",
    4: "RENDER",
    5: "COMPRESS",
    6: "QC_PROMOTE",
}
STAGE_PROGRESS = {i: 0 for i in range(1, 7)}
_LAST_STATUS_WRITE = 0.0
_LAST_REPORTED_PCT = -1


def report_progress(step: int, stage_pct: int, msg: str, force: bool = False) -> None:
    global _LAST_STATUS_WRITE, _LAST_REPORTED_PCT
    stage_pct = max(0, min(100, int(stage_pct)))
    STAGE_PROGRESS[step] = stage_pct
    overall_pct = int(sum(STAGE_PROGRESS.values()) / 6)
    now_str = datetime.now().strftime("%H:%M:%S")
    code = STAGE_NAMES[step]
    line = f"[{now_str}] TAHAP [{step}/6] {code} ({stage_pct}% | Total: {overall_pct}%): {msg}"
    print(line, flush=True)

    now = time.time()
    if force or abs(overall_pct - _LAST_REPORTED_PCT) >= 5 or (now - _LAST_STATUS_WRITE) >= 15:
        _LAST_STATUS_WRITE = now
        _LAST_REPORTED_PCT = overall_pct
        try:
            lines = [
                f"STATUS: RUNNING ({overall_pct}%)",
                f"JOB: {JOB_TITLE}",
                f"CURRENT: [{step}/6] {code} ({stage_pct}%)",
                f"MESSAGE: {msg}",
                "RINCIAN_TAHAP:",
            ]
            for idx in range(1, 7):
                lines.append(f"  - [{idx}/6] {STAGE_NAMES[idx]}: {STAGE_PROGRESS[idx]}%")
            STATUS_FILE.write_text("\n".join(lines) + "\n", encoding="utf-8")
        except Exception:
            pass


def run_streaming_cmd(
    cmd: list[str],
    cwd: Path | None = None,
    env: dict[str, str] | None = None,
    timeout_sec: int = 1800,
    on_line=None,
) -> tuple[int, list[str]]:
    proc = subprocess.Popen(
        cmd,
        cwd=str(cwd) if cwd else None,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        bufsize=0,
    )
    output_lines: list[str] = []
    buf = bytearray()
    start_ts = time.time()

    assert proc.stdout is not None
    while True:
        if time.time() - start_ts > timeout_sec:
            proc.kill()
            raise TimeoutError(f"Perintah melebihi batas waktu {timeout_sec}s: {' '.join(cmd[:4])}")
        ch = proc.stdout.read(1)
        if not ch:
            if proc.poll() is not None:
                break
            time.sleep(0.01)
            continue
        if ch in (b"\r", b"\n"):
            if buf:
                text_line = buf.decode("utf-8", errors="replace").strip()
                buf.clear()
                if text_line:
                    output_lines.append(text_line)
                    if len(output_lines) > 250:
                        output_lines = output_lines[-200:]
                    if on_line:
                        on_line(text_line)
        else:
            buf.extend(ch)

    if buf:
        text_line = buf.decode("utf-8", errors="replace").strip()
        if text_line:
            output_lines.append(text_line)
            if on_line:
                on_line(text_line)

    rc = proc.wait(timeout=30)
    return rc, output_lines


