def stage_1_setup() -> None:
    report_progress(1, 5, "Membersihkan sisa folder kerja yatim & menyiapkan direktori...", force=True)
    for orphan in WORK_ROOT.iterdir():
        if orphan.is_dir():
            shutil.rmtree(orphan, ignore_errors=True)
    if ERROR_LOG_FILE.exists():
        ERROR_LOG_FILE.unlink(missing_ok=True)

    WORK_DIR.mkdir(parents=True, exist_ok=True)
    (WORK_DIR / "public" / "sfx").mkdir(parents=True, exist_ok=True)
    for sub in ("npm", "node_template", "py_site", "hf", "chromium"):
        (CACHE_DIR / sub).mkdir(parents=True, exist_ok=True)

    py_site = CACHE_DIR / "py_site"
    if str(py_site) not in sys.path:
        sys.path.insert(0, str(py_site))
    os.environ["PYTHONPATH"] = f"{py_site}:{os.environ.get('PYTHONPATH', '')}"
    os.environ["NPM_CONFIG_CACHE"] = str(CACHE_DIR / "npm")
    os.environ["HF_HOME"] = str(CACHE_DIR / "hf")

    report_progress(1, 35, "Memeriksa paket Python edge-tts (zero-reinstall check)...")
    try:
        import edge_tts  # noqa: F401
        report_progress(1, 65, "edge-tts sudah tersedia di cache/VM (lewati pip install).")
    except ImportError:
        report_progress(1, 45, "Memasang edge-tts ke cache persisten...")
        subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "-q",
                "--no-warn-script-location",
                "--target",
                str(py_site),
                "edge-tts",
            ],
            check=True,
            timeout=300,
        )
        report_progress(1, 65, "edge-tts berhasil dipasang ke py_site.")

    report_progress(1, 80, "Memeriksa FFmpeg, ffprobe, Node.js, & Font Sistem...")
    if not shutil.which("ffmpeg") or not shutil.which("ffprobe"):
        raise RuntimeError("FFmpeg/ffprobe tidak ditemukan di runner. Pastikan FFmpeg terpasang.")

    node_ver = subprocess.check_output(["node", "-v"], text=True, timeout=15).strip()
    major = int(re.sub(r"^v", "", node_ver).split(".")[0])
    if major < 18:
        raise RuntimeError(f"Node.js >= 18 diperlukan, ditemukan {node_ver}")

    report_progress(1, 100, f"Lingkungan siap (Node {node_ver}, FFmpeg & edge-tts aktif).", force=True)


