def write_silence_wav(path: Path, duration_ms: int, sample_rate: int = 48000) -> float:
    num_samples = max(1, int(round((duration_ms / 1000.0) * sample_rate)))
    with wave.open(str(path), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(b"\x00\x00" * num_samples)
    return num_samples / float(sample_rate)


def get_wav_duration(path: Path) -> float:
    with wave.open(str(path), "rb") as wf:
        return wf.getnframes() / float(wf.getframerate())


def generate_procedural_bgm(path: Path, duration_sec: float, mood: str = "warm-pad", sr: int = 48000) -> None:
    total_samples = max(sr, int(math.ceil(duration_sec * sr)))
    # Warm cinematic chord progression (Cmaj7 -> Am7 -> Fmaj7 -> G6)
    chords = [
        (130.81, 164.81, 196.00, 246.94),
        (110.00, 130.81, 164.81, 196.00),
        (87.31, 130.81, 164.81, 220.00),
        (98.00, 146.83, 196.00, 220.00),
    ]
    bar_samples = sr * 4
    with wave.open(str(path), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)
        chunk_size = 4800
        for start in range(0, total_samples, chunk_size):
            end = min(total_samples, start + chunk_size)
            frames = bytearray()
            for i in range(start, end):
                t = i / float(sr)
                chord = chords[(i // bar_samples) % len(chords)]
                bar_pos = (i % bar_samples) / float(bar_samples)
                swell = 0.72 + 0.28 * math.sin(math.pi * bar_pos)
                sig = 0.0
                for idx_f, f in enumerate(chord):
                    detune = 1.0 + (idx_f - 1.5) * 0.0018
                    sig += math.sin(2.0 * math.pi * f * detune * t)
                sig = (sig / len(chord)) * swell * 0.55
                sample = max(-32767, min(32767, int(sig * 32767)))
                frames.extend(struct.pack("<h", sample))
            wf.writeframes(frames)


def generate_procedural_sfx(sfx_dir: Path, sr: int = 48000) -> None:
    rng = random.Random(42)

    def save_samples(name: str, samples: list[float]) -> None:
        out = sfx_dir / f"{name}.wav"
        with wave.open(str(out), "wb") as wf:
            wf.setnchannels(1)
            wf.setsampwidth(2)
            wf.setframerate(sr)
            raw = bytearray()
            for s in samples:
                val = max(-32767, min(32767, int(s * 32767)))
                raw.extend(struct.pack("<h", val))
            wf.writeframes(raw)

    # 1. whoosh.wav (0.40s smooth filtered sweep)
    n_whoosh = int(0.40 * sr)
    lp = 0.0
    whoosh_samples = []
    for i in range(n_whoosh):
        u = i / float(n_whoosh)
        env = math.sin(math.pi * u) ** 1.6
        white = rng.uniform(-1.0, 1.0)
        alpha = 0.06 + 0.18 * math.sin(math.pi * u)
        lp = lp + alpha * (white - lp)
        whoosh_samples.append(lp * env * 0.65)
    save_samples("whoosh", whoosh_samples)

    # 2. pop.wav (0.18s crisp upward-downward bubble pop)
    n_pop = int(0.18 * sr)
    pop_samples = []
    phase = 0.0
    for i in range(n_pop):
        u = i / float(n_pop)
        env = math.exp(-u * 14.0) * min(1.0, u * 40.0)
        freq = 320.0 + 460.0 * math.exp(-u * 18.0)
        phase += 2.0 * math.pi * freq / sr
        pop_samples.append(math.sin(phase) * env * 0.72)
    save_samples("pop", pop_samples)

    # 3. tick.wav (0.12s short mechanical/quill tick)
    n_tick = int(0.12 * sr)
    tick_samples = []
    for i in range(n_tick):
        u = i / float(n_tick)
        env = math.exp(-u * 35.0)
        s = (math.sin(2.0 * math.pi * 1250.0 * (i / sr)) * 0.6 + rng.uniform(-0.4, 0.4)) * env
        tick_samples.append(s * 0.65)
    save_samples("tick", tick_samples)

    # 4. chime.wav (0.32s warm harmonic bell chime)
    n_chime = int(0.32 * sr)
    chime_samples = []
    for i in range(n_chime):
        t = i / float(sr)
        u = i / float(n_chime)
        env = math.exp(-u * 7.5) * min(1.0, u * 50.0)
        s = (
            math.sin(2.0 * math.pi * 587.33 * t) * 0.55
            + math.sin(2.0 * math.pi * 880.00 * t) * 0.30
            + math.sin(2.0 * math.pi * 1174.66 * t) * 0.15
        ) * env
        chime_samples.append(s * 0.68)
    save_samples("chime", chime_samples)

    # 5. thud.wav (0.24s deep low-end impact)
    n_thud = int(0.24 * sr)
    thud_samples = []
    phase = 0.0
    for i in range(n_thud):
        u = i / float(n_thud)
        env = math.exp(-u * 11.0) * min(1.0, u * 60.0)
        freq = 95.0 - 52.0 * u
        phase += 2.0 * math.pi * freq / sr
        thud_samples.append(math.sin(phase) * env * 0.80)
    save_samples("thud", thud_samples)


async def synth_clause_mp3(spoken_text: str, out_mp3: Path, is_question: bool) -> None:
    import edge_tts

    pitch = "+1Hz" if is_question else BASE_PITCH
    rate = "-3%" if not is_question and len(spoken_text.split()) <= 6 else BASE_RATE
    for attempt in range(3):
        try:
            comm = edge_tts.Communicate(spoken_text, VOICE_NAME, rate=rate, pitch=pitch)
            await comm.save(str(out_mp3))
            if out_mp3.exists() and out_mp3.stat().st_size > 200:
                return
        except Exception:
            if attempt == 2:
                raise
            await asyncio.sleep(1.2 * (attempt + 1))


async def synth_all_clauses(tasks_spec: list[tuple[str, Path, bool]]) -> None:
    sem = asyncio.Semaphore(4)

    async def worker(text: str, path: Path, is_q: bool) -> None:
        async with sem:
            await synth_clause_mp3(text, path, is_q)

    await asyncio.gather(*(worker(t, p, q) for t, p, q in tasks_spec))


def stage_2_audio() -> dict:
    report_progress(2, 5, "Menyiapkan sintesis VO Edge-TTS naturalisasi lisan Indonesia...", force=True)
    audio_tmp = WORK_DIR / "audio_tmp"
    audio_tmp.mkdir(parents=True, exist_ok=True)

    tasks_spec: list[tuple[str, Path, bool]] = []
    clause_records: list[dict] = []

    for s_idx, seg in enumerate(SEGMENTS):
        for c_idx, (disp, spok, pause_ms) in enumerate(seg["clauses"]):
            mp3_path = audio_tmp / f"s{s_idx}_c{c_idx}.mp3"
            wav_path = audio_tmp / f"s{s_idx}_c{c_idx}.wav"
            is_q = disp.strip().endswith("?")
            tasks_spec.append((spok, mp3_path, is_q))
            clause_records.append(
                {
                    "scene_idx": s_idx,
                    "scene_id": seg["id"],
                    "display": disp,
                    "spoken": spok,
                    "pause_ms": pause_ms,
                    "mp3": mp3_path,
                    "wav": wav_path,
                }
            )

    asyncio.run(synth_all_clauses(tasks_spec))
    report_progress(2, 45, "Memangkas dead-air (45ms, -54dB) & menyisipkan jeda napas terkalibrasi...")

    concat_list: list[Path] = []
    for idx, rec in enumerate(clause_records):
        # Trim leading/trailing silence safely with 45ms consonant cushion
        trim_filter = (
            "silenceremove=start_periods=1:start_duration=0.045:start_threshold=-54dB,"
            "areverse,"
            "silenceremove=start_periods=1:start_duration=0.045:start_threshold=-54dB,"
            "areverse"
        )
        subprocess.run(
            [
                "ffmpeg",
                "-y",
                "-i",
                str(rec["mp3"]),
                "-af",
                trim_filter,
                "-ar",
                "48000",
                "-ac",
                "1",
                "-c:a",
                "pcm_s16le",
                str(rec["wav"]),
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=True,
            timeout=60,
        )
        rec["dur_sec"] = get_wav_duration(rec["wav"])
        concat_list.append(rec["wav"])

        sil_path = audio_tmp / f"sil_{idx}.wav"
        rec["actual_pause_sec"] = write_silence_wav(sil_path, rec["pause_ms"], 48000)
        concat_list.append(sil_path)

    # Extra 0.45s tail silence on final scene
    tail_sil = audio_tmp / "sil_tail.wav"
    tail_sec = write_silence_wav(tail_sil, 450, 48000)
    concat_list.append(tail_sil)

    concat_txt = audio_tmp / "concat.txt"
    concat_txt.write_text(
        "\n".join(f"file '{p.as_posix()}'" for p in concat_list) + "\n",
        encoding="utf-8",
    )

    raw_joined = audio_tmp / "raw_joined.wav"
    subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-f",
            "concat",
            "-safe",
            "0",
            "-i",
            str(concat_txt),
            "-c:a",
            "pcm_s16le",
            str(raw_joined),
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=True,
        timeout=120,
    )

    report_progress(2, 70, "Menjalankan Mastering Studio Warmth FFmpeg (-16 LUFS / -1.5 dBTP)...")
    vo_out = WORK_DIR / "public" / "vo.wav"
    studio_warmth = (
        "highpass=f=80,"
        "equalizer=f=220:t=q:w=1.2:g=2.0,"
        "equalizer=f=3200:t=q:w=1.5:g=2.5,"
        "equalizer=f=6800:t=q:w=2.0:g=-2.5,"
        "acompressor=threshold=-18dB:ratio=2.5:attack=15:release=120:makeup=2,"
        "loudnorm=I=-16:TP=-1.5:LRA=9,"
        "alimiter=limit=0.84:level=disabled"
    )
    subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-i",
            str(raw_joined),
            "-af",
            studio_warmth,
            "-ar",
            "48000",
            "-ac",
            "1",
            "-c:a",
            "pcm_s16le",
            str(vo_out),
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=True,
        timeout=120,
    )

    # Build exact word-level & scene-level timestamps
    cursor_sec = 0.0
    words_tokens: list[dict] = []
    scene_bounds: dict[int, dict] = {}
    last_end_frame = 0

    for rec in clause_records:
        s_idx = rec["scene_idx"]
        if s_idx not in scene_bounds:
            scene_bounds[s_idx] = {
                "id": rec["scene_id"],
                "start_sec": cursor_sec,
            }

        c_start = cursor_sec
        c_dur = rec["dur_sec"]
        disp_words = [w for w in rec["display"].split() if w]
        weights = [max(2, len(re.sub(r"[^A-Za-z0-9]", "", w))) for w in disp_words]
        total_w = max(1, sum(weights))

        w_cursor = c_start
        for w, wt in zip(disp_words, weights):
            w_dur = c_dur * (wt / float(total_w))
            sf = max(last_end_frame, int(round(w_cursor * FPS)))
            ef = max(sf + 2, int(round((w_cursor + w_dur) * FPS)))
            words_tokens.append(
                {
                    "word": w,
                    "startFrame": sf,
                    "endFrame": ef,
                }
            )
            last_end_frame = ef
            w_cursor += w_dur

        cursor_sec += c_dur + rec["actual_pause_sec"]
        scene_bounds[s_idx]["end_sec"] = cursor_sec

    cursor_sec += tail_sec
    scene_bounds[len(SEGMENTS) - 1]["end_sec"] = cursor_sec

    total_frames = max(last_end_frame + 12, int(math.ceil(cursor_sec * FPS)))
    scenes_manifest: list[dict] = []
    for s_idx in range(len(SEGMENTS)):
        sb = scene_bounds[s_idx]
        sf = int(round(sb["start_sec"] * FPS))
        ef = total_frames if s_idx == len(SEGMENTS) - 1 else int(round(sb["end_sec"] * FPS))
        scenes_manifest.append(
            {
                "id": sb["id"],
                "startFrame": sf,
                "durationInFrames": max(24, ef - sf),
            }
        )

    # Map procedural SFX events synchronized to scenes
    sfx_events: list[dict] = [
        {"type": "thud", "frame": 6, "volume": 0.18},
        {"type": "pop", "frame": 24, "volume": 0.16},
    ]
    for idx, sc in enumerate(scenes_manifest):
        sf = sc["startFrame"]
        dur = sc["durationInFrames"]
        if idx > 0:
            sfx_events.append({"type": "whoosh", "frame": max(0, sf - 9), "volume": 0.15})
        if idx == 1:
            sfx_events.append({"type": "thud", "frame": sf + 10, "volume": 0.17})
            sfx_events.append({"type": "chime", "frame": sf + 50, "volume": 0.16})
        elif idx == 2:
            sfx_events.append({"type": "tick", "frame": sf + 24, "volume": 0.13})
            sfx_events.append({"type": "pop", "frame": sf + 56, "volume": 0.16})
        elif idx == 3:
            sfx_events.append({"type": "tick", "frame": sf + 22, "volume": 0.13})
            sfx_events.append({"type": "tick", "frame": sf + 48, "volume": 0.13})
            sfx_events.append({"type": "chime", "frame": sf + 95, "volume": 0.15})
        elif idx == 4:
            sfx_events.append({"type": "pop", "frame": sf + 28, "volume": 0.16})
            sfx_events.append({"type": "chime", "frame": sf + 60, "volume": 0.17})
        elif idx == 5:
            sfx_events.append({"type": "thud", "frame": sf + 14, "volume": 0.16})
        elif idx == 6:
            sfx_events.append({"type": "chime", "frame": sf + 18, "volume": 0.17})

    report_progress(2, 88, "Membangkitkan BGM ambient & efek suara prosedural lokal 48kHz...")
    generate_procedural_bgm(WORK_DIR / "public" / "bgm.wav", total_frames / float(FPS), BGM_MOOD, 48000)
    generate_procedural_sfx(WORK_DIR / "public" / "sfx", 48000)

    manifest = {
        "fps": FPS,
        "totalFrames": total_frames,
        "styleCode": STYLE_CODE,
        "bgmMood": BGM_MOOD,
        "scenes": scenes_manifest,
        "words": words_tokens,
        "sfxEvents": sfx_events,
    }
    (WORK_DIR / "public" / "manifest.json").write_text(
        json.dumps(manifest, indent=2), encoding="utf-8"
    )
    report_progress(2, 100, f"Audio & manifest selesai ({total_frames} frame / {total_frames / FPS:.1f} dtk).", force=True)
    return manifest


# ==============================================================================
# 5. TAHAP [3/6] PROJECT — DECODE BASE64 & HYDRATE CACHE (.TAR)
# ==============================================================================
def stage_3_project() -> None:
    report_progress(3, 10, "Mendekode seluruh file proyek Remotion 4.x dari base64...", force=True)
    for rel_path, b64_data in ENCODED_PROJECT_FILES.items():
        target = WORK_DIR / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(b64_data))

    report_progress(3, 30, "Memeriksa cache node_modules (.tar)...")
    pkg_hash = hashlib.sha256((WORK_DIR / "package.json").read_bytes()).hexdigest()
    node_cache_dir = CACHE_DIR / "node_template"
    hash_file = node_cache_dir / "pkg.hash"
    tar_file = node_cache_dir / "node_modules.tar"

    if hash_file.exists() and hash_file.read_text().strip() == pkg_hash and tar_file.exists():
        report_progress(3, 50, "Mengekstrak node_modules.tar ke SSD lokal (< 3 detik)...")
        subprocess.run(["tar", "-xf", str(tar_file), "-C", str(WORK_DIR)], check=True, timeout=180)
        bin_dir = WORK_DIR / "node_modules" / ".bin"
        if bin_dir.exists():
            subprocess.run(["chmod", "-R", "+x", str(bin_dir)], check=False, timeout=30)
    else:
        report_progress(3, 45, "Menjalankan npm install (pertama kali) & membuat arsip cache...")
        subprocess.run(
            ["npm", "install", "--no-audit", "--no-fund", "--prefer-offline"],
            cwd=str(WORK_DIR),
            check=True,
            timeout=600,
        )
        subprocess.run(["tar", "-cf", str(tar_file), "-C", str(WORK_DIR), "node_modules"], check=True, timeout=300)
        hash_file.write_text(pkg_hash, encoding="utf-8")

    report_progress(3, 75, "Memeriksa cache Chromium Headless Shell...")
    chromium_tar = CACHE_DIR / "chromium" / "chromium.tar"
    env = os.environ.copy()
    env["PUPPETEER_CACHE_DIR"] = str(CHROMIUM_DIR)
    env["PLAYWRIGHT_BROWSERS_PATH"] = str(CHROMIUM_DIR)

    if chromium_tar.exists() and not any(CHROMIUM_DIR.iterdir()):
        subprocess.run(["tar", "-xf", str(chromium_tar), "-C", str(CHROMIUM_DIR)], check=True, timeout=180)
        subprocess.run(["chmod", "-R", "+x", str(CHROMIUM_DIR)], check=False, timeout=30)

    rc, _ = run_streaming_cmd(["npx", "remotion", "compositions", "src/index.ts"], cwd=WORK_DIR, env=env, timeout_sec=300)
    if rc != 0:
        subprocess.run(["npx", "remotion", "browser", "ensure"], cwd=str(WORK_DIR), env=env, check=True, timeout=600)

    if any(CHROMIUM_DIR.iterdir()) and not chromium_tar.exists():
        subprocess.run(["tar", "-cf", str(chromium_tar), "-C", str(CHROMIUM_DIR), "."], check=False, timeout=300)

    report_progress(3, 100, "Proyek Remotion & Chromium siap dirender.", force=True)


# ==============================================================================
# 6. TAHAP [4/6] RENDER — MULTI-CORE CPU OPTIMAL & SMART FALLBACK
# ==============================================================================
def stage_4_render(total_frames: int) -> None:
    report_progress(4, 2, "Memulai bundling & render Remotion (1080x1920 @ 24fps)...", force=True)
    cpu_cnt = os.cpu_count() or 2
    concurrency = max(2, min(4, cpu_cnt))
    mem_mb = 4096 if cpu_cnt >= 4 else 2048

    env = os.environ.copy()
    env["NODE_OPTIONS"] = f"--max-old-space-size={mem_mb}"
    env["PUPPETEER_CACHE_DIR"] = str(CHROMIUM_DIR)
    env["PLAYWRIGHT_BROWSERS_PATH"] = str(CHROMIUM_DIR)

    raw_mp4 = WORK_DIR / "raw_out.mp4"
    timeout_sec = max(1800, int(total_frames * 1.2) + 300)
    last_frame_ts = time.time()

    def parse_remotion_line(line: str) -> None:
        nonlocal last_frame_ts
        m = re.search(r"(\d+)\s*/\s*(\d+)", line)
        if m:
            cur = int(m.group(1))
            tot = max(1, int(m.group(2)))
            if tot == total_frames or cur <= tot:
                last_frame_ts = time.time()
                pct = 5 + int((cur / float(tot)) * 90)
                report_progress(4, min(95, pct), f"Merender frame {cur}/{tot}...")
        elif "Stitching" in line or "Combining" in line:
            report_progress(4, 97, "Menggabungkan frame & trek audio...")

    primary_cmd = [
        "npx",
        "remotion",
        "render",
        "src/index.ts",
        "MainComp",
        str(raw_mp4),
        "--codec=h264",
        "--x264-preset=ultrafast",
        "--crf=18",
        f"--jpeg-quality={JPEG_QUALITY}",
        "--pixel-format=yuv420p",
        f"--concurrency={concurrency}",
        "--gl=swangle",
        "--log=verbose",
    ]

    rc, logs = run_streaming_cmd(primary_cmd, cwd=WORK_DIR, env=env, timeout_sec=timeout_sec, on_line=parse_remotion_line)
    if rc != 0 or not raw_mp4.exists() or raw_mp4.stat().st_size < 50_000:
        report_progress(4, 15, "Jalur utama gagal/OOM; menjalankan Smart Fallback (--concurrency=1)...", force=True)
        fallback_cmd = [
            "npx",
            "remotion",
            "render",
            "src/index.ts",
            "MainComp",
            str(raw_mp4),
            "--codec=h264",
            "--x264-preset=ultrafast",
            "--crf=18",
            "--jpeg-quality=70",
            "--pixel-format=yuv420p",
            "--concurrency=1",
            "--gl=angle",
            "--use-angle=swiftshader",
            "--log=verbose",
        ]
        rc2, logs2 = run_streaming_cmd(fallback_cmd, cwd=WORK_DIR, env=env, timeout_sec=timeout_sec, on_line=parse_remotion_line)
        if rc2 != 0 or not raw_mp4.exists():
            tail_err = "\n".join((logs + logs2)[-30:])
            raise RuntimeError(f"Remotion render gagal (exit {rc2}):\n{tail_err}")

    report_progress(4, 100, "Render mentah selesai.", force=True)


# ==============================================================================
# 7. TAHAP [5/6] COMPRESS — SOCIAL MASTERING H.264 + -14 LUFS
# ==============================================================================
def stage_5_compress(total_frames: int) -> None:
    report_progress(5, 2, "Mengompresi MP4 final (H.264 High 4.1 + AAC 128k -14 LUFS)...", force=True)
    raw_mp4 = WORK_DIR / "raw_out.mp4"
    final_mp4 = WORK_DIR / "final_out.mp4"
    total_us = max(1.0, (total_frames / float(FPS)) * 1_000_000.0)

    def on_ffmpeg_line(line: str) -> None:
        if line.startswith("out_time_us="):
            try:
                us = float(line.split("=", 1)[1])
                pct = min(99, max(1, int((us / total_us) * 100)))
                report_progress(5, pct, f"Encoding H.264 & Loudnorm ({pct}%)...")
            except ValueError:
                pass

    cmd = [
        "ffmpeg",
        "-y",
        "-i",
        str(raw_mp4),
        "-c:v",
        "libx264",
        "-preset",
        "veryfast",
        "-crf",
        "21",
        "-maxrate",
        "6M",
        "-bufsize",
        "12M",
        "-profile:v",
        "high",
        "-level",
        "4.1",
        "-pix_fmt",
        "yuv420p",
        "-af",
        "loudnorm=I=-14:TP=-1.5:LRA=11",
        "-c:a",
        "aac",
        "-b:a",
        "128k",
        "-ar",
        "48000",
        "-movflags",
        "+faststart",
        "-progress",
        "pipe:1",
        "-nostats",
        str(final_mp4),
    ]
    rc, logs = run_streaming_cmd(cmd, cwd=WORK_DIR, timeout_sec=600, on_line=on_ffmpeg_line)
    if rc != 0 or not final_mp4.exists():
        raise RuntimeError(f"FFmpeg compress gagal:\n" + "\n".join(logs[-20:]))
    report_progress(5, 100, "Kompresi MP4 siap unggah selesai.", force=True)


# ==============================================================================
# 8. TAHAP [6/6] QC_PROMOTE — QUALITY GATE FFPROBE & AUTO-COVER PNG
# ==============================================================================
def stage_6_qc_promote() -> dict:
    report_progress(6, 20, "Menjalankan Quality Gate ffprobe (integritas, sync A/V, bitrate)...", force=True)
    final_mp4 = WORK_DIR / "final_out.mp4"
    cover_png = WORK_DIR / "cover_out.png"

    size_bytes = final_mp4.stat().st_size if final_mp4.exists() else 0
    if size_bytes < 100_000:
        raise RuntimeError(f"QC Gagal: Ukuran MP4 terlalu kecil ({size_bytes} bytes)")

    probe_raw = subprocess.check_output(
        [
            "ffprobe",
            "-v",
            "error",
            "-show_entries",
            "format=duration,bit_rate:stream=codec_type,duration,width,height",
            "-of",
            "json",
            str(final_mp4),
        ],
        text=True,
        timeout=30,
    )
    probe = json.loads(probe_raw)
    streams = probe.get("streams", [])
    v_stream = next((s for s in streams if s.get("codec_type") == "video"), None)
    a_stream = next((s for s in streams if s.get("codec_type") == "audio"), None)
    if not v_stream or not a_stream:
        raise RuntimeError("QC Gagal: Stream video atau audio hilang pada hasil akhir.")

    fmt = probe.get("format", {})
    duration = float(fmt.get("duration") or v_stream.get("duration") or 0.0)
    v_dur = float(v_stream.get("duration") or duration)
    a_dur = float(a_stream.get("duration") or duration)
    av_drift = abs(v_dur - a_dur)
    bitrate_mbps = int(fmt.get("bit_rate") or 0) / 1_000_000.0

    if av_drift >= 0.25:
        raise RuntimeError(f"QC Gagal: Selisih durasi audio-video {av_drift:.3f}s >= 0.25s")
    if bitrate_mbps > 9.0:
        raise RuntimeError(f"QC Gagal: Bitrate {bitrate_mbps:.2f} Mbps > 9.0 Mbps")

    report_progress(6, 65, "Mengekstrak sampul tajam cover.png pada puncak hook...", force=True)
    ss_hook = min(1.2, max(0.3, duration * 0.08))
    subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-ss",
            f"{ss_hook:.2f}",
            "-i",
            str(final_mp4),
            "-vframes",
            "1",
            "-q:v",
            "2",
            str(cover_png),
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=True,
        timeout=30,
    )

    dest_mp4 = OUTPUT_DIR / f"{JOB_TITLE}_final.mp4"
    dest_cover = OUTPUT_DIR / f"{JOB_TITLE}_cover.png"
    dest_report = OUTPUT_DIR / f"{JOB_TITLE}_render_report.json"

    shutil.copy2(final_mp4, dest_mp4)
    if cover_png.exists():
        shutil.copy2(cover_png, dest_cover)

    report_data = {
        "status": "COMPLETED",
        "job_title": JOB_TITLE,
        "style_code": STYLE_CODE,
        "duration_sec": round(duration, 2),
        "size_mb": round(size_bytes / (1024 * 1024), 2),
        "bitrate_mbps": round(bitrate_mbps, 2),
        "av_drift_sec": round(av_drift, 3),
        "resolution": f"{v_stream.get('width')}x{v_stream.get('height')}",
        "fps": FPS,
        "mp4_path": str(dest_mp4),
        "cover_path": str(dest_cover),
    }
    dest_report.write_text(json.dumps(report_data, indent=2), encoding="utf-8")

    report_progress(6, 100, f"QC LULUS! MP4 ({report_data['size_mb']} MB) & Cover siap.", force=True)
    STATUS_FILE.write_text(
        "STATUS: COMPLETED\n"
        f"MP4: {dest_mp4}\n"
        f"COVER: {dest_cover}\n"
        f"DURATION: {report_data['duration_sec']}s\n"
        f"SIZE_MB: {report_data['size_mb']} MB\n"
        f"BITRATE: {report_data['bitrate_mbps']} Mbps\n"
        "RINCIAN_TAHAP:\n"
        + "\n".join(f"  - [{i}/6] {STAGE_NAMES[i]}: 100%" for i in range(1, 7))
        + "\n",
        encoding="utf-8",
    )
    return report_data


def main() -> int:
    try:
        stage_1_setup()
        manifest = stage_2_audio()
        stage_3_project()
        stage_4_render(manifest["totalFrames"])
        stage_5_compress(manifest["totalFrames"])
        rep = stage_6_qc_promote()
        print("RINGKASAN_AKHIR:", json.dumps(rep), flush=True)
        return 0
    except Exception as exc:
        err_msg = f"STATUS: FAILED\nERROR: {exc}\n"
        print(err_msg, file=sys.stderr, flush=True)
        try:
            STATUS_FILE.write_text(err_msg, encoding="utf-8")
            ERROR_LOG_FILE.write_text(err_msg, encoding="utf-8")
        except Exception:
            pass
        return 1
    finally:
        if WORK_DIR.exists():
            shutil.rmtree(WORK_DIR, ignore_errors=True)


if __name__ == "__main__":
    sys.exit(main())
